// Evaluation results inside the app, so reviewers can see how recommendations are checked
// without opening the repo. Shows the last full run (generated by `npm run eval`, 384
// synthetic people) and can re-run a smaller quick check right here in the browser.
import { useState } from 'react';
import { CheckCircle2, XCircle } from 'lucide-react';
import { Button, Notice, PageHeader, Stat, Tag } from '../../components/ui.tsx';
import { CAT } from '../../lib/catalog.ts';
import { DIET_LABELS } from '../../domain/diet.ts';
import type { DietPattern } from '../../domain/types.ts';
import type { EvalReport, Gate } from '../../eval/report.ts';
import saved from '../../eval/latest-report.json';

const GROUP_ORDER: Gate['group'][] = ['Safety', 'Nutrition', 'Grocery', 'Scope', 'Reliability', 'Voice intake', 'Store matching'];
const GROUP_NOTE: Record<Gate['group'], string> = {
  Safety: 'Hard rules. A single failure fails the whole evaluation.',
  Nutrition: 'Each planned day is checked against the person’s own energy range and protein floor.',
  Grocery: 'The basket must cover the plan and be honest about the budget.',
  Scope: 'People we should not plan for (under 18, pregnancy, kidney disease and so on) must be refused.',
  Reliability: 'Same input gives the same answer; options are genuinely different.',
  'Voice intake': 'How well spoken or typed descriptions are turned into profile fields.',
  'Store matching': 'Whether real store product titles are mapped to the right ingredient, or safely refused.',
};

const pct = (n: number) => `${(n * 100).toFixed(1)}%`;

export function EvaluationPage() {
  const [report, setReport] = useState<EvalReport>(saved as unknown as EvalReport);
  const [running, setRunning] = useState(false);
  const [isLive, setIsLive] = useState(false);

  async function runQuick() {
    setRunning(true);
    // Let the button show its spinner before the (synchronous) run blocks the main thread.
    await new Promise((r) => setTimeout(r, 50));
    const { runFullEvaluation } = await import('../../eval/report.ts');
    setReport(runFullEvaluation(CAT, 'quick'));
    setIsLive(true);
    setRunning(false);
  }

  const r = report.recommendation;
  const failed = report.gates.filter((g) => !g.pass);
  const criticalFailed = failed.filter((g) => g.critical);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Evaluation"
        description="How we check that every recommendation respects the person’s diet, allergies, exclusions, nutrition targets and budget."
        actions={
          <Button variant="tonal" onClick={runQuick} loading={running}>
            Run a quick check now
          </Button>
        }
      />

      <Notice tone={report.passed ? 'success' : 'danger'} title={report.passed ? `All ${report.gates.length} checks passed` : `${failed.length} of ${report.gates.length} checks failed`}>
        {isLive ? 'Quick check run just now in your browser' : `Full run from ${new Date(report.generatedAt).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}`} with planner {report.versions.planner}, reader {report.versions.extractor} and matcher {report.versions.matcher}.
        {criticalFailed.length > 0 && ` Critical failures: ${criticalFailed.map((g) => g.id).join(', ')}.`}
      </Notice>

      <section className="card p-5">
        <h2 className="text-lg font-medium">How the check works</h2>
        <div className="mt-2 max-w-prose space-y-2 text-sm text-on-surface-variant">
          <p>
            We generate {r.profiles} synthetic adults covering every food pattern, eight allergy combinations and four sets of strict exclusions. For each one the app builds its meal plans, cheaper alternatives and grocery basket exactly as it would for a real person.
          </p>
          <p>
            A separate checker, written independently of the planner and sharing none of its code, then re-reads every meal ingredient by ingredient and every product in the basket. It flags any egg, meat or fish in a vegetarian plan, any allergen, any excluded food, and any day outside the person’s energy range or below their protein floor.
          </p>
          <p>Zero problems in a sample cannot prove the true rate is zero, so each safety check also reports a 95% upper bound (the “rule of three”).</p>
        </div>
      </section>

      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <Stat label="People simulated" value={r.profiles.toLocaleString('en-IN')} sub={`${r.feasible} got a valid plan`} />
        <Stat label="Meals re-checked" value={r.mealsChecked.toLocaleString('en-IN')} sub={`${r.plansChecked.toLocaleString('en-IN')} plans`} />
        <Stat label="Safety violations" value={r.violations.diet + r.violations.allergen + r.violations.exclusion + r.violations.product} sub="diet, allergen, exclusion, product" />
        <Stat label="Days on target" value={pct(r.energyDaysTotal ? r.energyDaysOk / r.energyDaysTotal : 0)} sub={`protein ${pct(r.proteinDaysTotal ? r.proteinDaysOk / r.proteinDaysTotal : 0)}`} />
      </div>

      {GROUP_ORDER.map((group) => {
        const gates = report.gates.filter((g) => g.group === group);
        if (!gates.length) return null;
        return (
          <section key={group} className="card overflow-hidden">
            <div className="px-5 pt-5">
              <h2 className="text-lg font-medium">{group}</h2>
              <p className="text-sm text-on-surface-variant">{GROUP_NOTE[group]}</p>
            </div>
            <ul className="mt-3 divide-y divide-outline-variant">
              {gates.map((g) => (
                <li key={g.id} className="grid grid-cols-[auto_1fr] gap-3 px-5 py-3 sm:grid-cols-[auto_1fr_14rem]">
                  {g.pass ? <CheckCircle2 className="mt-0.5 h-5 w-5 text-success" aria-label="Passed" /> : <XCircle className="mt-0.5 h-5 w-5 text-error" aria-label="Failed" />}
                  <div>
                    <p className="font-medium">
                      {g.name} {g.critical && <Tag tone="danger">Critical</Tag>}
                    </p>
                    <p className="text-xs text-on-surface-variant">Check {g.id}. Must be {g.threshold}.</p>
                  </div>
                  <p className="col-start-2 text-sm sm:col-start-3 sm:text-right">{g.measured}</p>
                </li>
              ))}
            </ul>
          </section>
        );
      })}

      <section className="card p-5">
        <h2 className="text-lg font-medium">By food pattern</h2>
        <table className="mt-3 w-full text-sm">
          <thead className="text-left text-on-surface-variant">
            <tr>
              <th className="py-2 font-medium">Pattern</th>
              <th className="py-2 text-right font-medium">People</th>
              <th className="py-2 text-right font-medium">Valid plan</th>
              <th className="py-2 text-right font-medium">Violations</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-outline-variant">
            {(Object.keys(r.byDiet) as DietPattern[]).map((d) => (
              <tr key={d}>
                <td className="py-2">{DIET_LABELS[d]}</td>
                <td className="py-2 text-right">{r.byDiet[d].profiles}</td>
                <td className="py-2 text-right">{r.byDiet[d].feasible}</td>
                <td className="py-2 text-right">{r.byDiet[d].violations}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <section className="card p-5">
        <h2 className="text-lg font-medium">Reading spoken descriptions</h2>
        <p className="mt-1 text-sm text-on-surface-variant">
          {report.extraction.cases} hand-labelled descriptions, including corrections (“no allergies, oh wait, fish”), negations (“not diabetic”) and Hinglish food names. A critical error is anything that would make a plan less safe, such as missing an allergy or reading “vegetarian” as “eggetarian”.
        </p>
        <div className="mt-3 grid grid-cols-3 gap-3">
          <Stat label="Precision" value={pct(report.extraction.overall.precision)} />
          <Stat label="Recall" value={pct(report.extraction.overall.recall)} />
          <Stat label="Critical errors" value={report.extraction.criticalErrors} sub={`${report.extraction.safeOverRestrictions} safe over-restrictions`} />
        </div>
      </section>

      <section className="card p-5">
        <h2 className="text-lg font-medium">Matching store products</h2>
        <p className="mt-1 text-sm text-on-surface-variant">
          {report.matching.cases} real-style product titles, including traps like “Eggless mayo”, “Chicken masala powder” and “Brown basmati”. When unsure, the matcher refuses rather than guesses.
        </p>
        <div className="mt-3 grid grid-cols-3 gap-3">
          <Stat label="Right when it maps" value={pct(report.matching.precisionWhenMapped)} />
          <Stat label="Correct refusals" value={`${report.matching.correctlyRefused}/${report.matching.shouldNotMap}`} />
          <Stat label="Pack sizes read" value={`${report.matching.packCorrect}/${report.matching.packCases}`} />
        </div>
      </section>

      <Notice title="What this does not prove">
        The checks use our sample food data and Hyderabad catalogue, not live store stock. Nutrition targets are reference estimates for healthy adults, not medical advice. Synthetic people cover the combinations we chose; real descriptions can be messier than our {report.extraction.cases} labelled examples.
      </Notice>
    </div>
  );
}
